// src/components/AiCompanion.js
import React, { useState } from 'react';
import styled from 'styled-components';

const CompanionContainer = styled.div`
  margin: 20px 0;
  padding: 20px;
  border-radius: 8px;
  background-color: #f3f4f6;
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
`;

const Message = styled.p`
  margin: 10px 0;
  font-size: 1rem;
`;

const Input = styled.input`
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border-radius: 5px;
  border: 1px solid #ddd;
`;

const Button = styled.button`
  padding: 10px;
  width: 100%;
  border: none;
  border-radius: 5px;
  background-color: #007bff;
  color: white;
  cursor: pointer;
  margin-top: 10px;

  &:hover {
    background-color: #0056b3;
  }
`;

const AiCompanion = () => {
  const [step, setStep] = useState(0);
  const [userLevel, setUserLevel] = useState('');
  const [gearSuggestions, setGearSuggestions] = useState('');

  const steps = [
    'Welcome! Are you new to triathlons, or do you have some experience?',
    'What kind of event are you preparing for? (Sprint, Olympic, Ironman)',
    'Great! Let me recommend some essential gear for you.',
  ];

  const nextStep = () => setStep((prev) => Math.min(prev + 1, steps.length - 1));
  const prevStep = () => setStep((prev) => Math.max(prev - 1, 0));

  const handleUserLevel = (e) => {
    setUserLevel(e.target.value.toLowerCase());
    if (e.target.value.toLowerCase() === 'beginner') {
      setGearSuggestions('For beginners, focus on essentials: a bike, helmet, and comfortable shoes.');
    } else {
      setGearSuggestions(
        'For experienced athletes, consider advanced wetsuits, aero bikes, and performance shoes.'
      );
    }
  };

  return (
    <CompanionContainer>
      <Message>{steps[step]}</Message>

      {step === 0 && (
        <Input
          type="text"
          placeholder="Enter 'Beginner' or 'Experienced'"
          onBlur={handleUserLevel}
        />
      )}

      {step === 2 && gearSuggestions && <Message>{gearSuggestions}</Message>}

      <div>
        <Button onClick={prevStep} disabled={step === 0}>
          Previous
        </Button>
        <Button onClick={nextStep} disabled={step === steps.length - 1}>
          Next
        </Button>
      </div>
    </CompanionContainer>
  );
};

export default AiCompanion;
